## **현재 구조의 문제점**

### 1. **불필요한 간접 계층**
- NavigationHelper → Channel → Flow → MainActivity → NavController
- 단순한 네비게이션을 위해 너무 복잡한 구조

### 2. **제한적인 사용**
- NavigationHelper는 오직 **MainActivity**와 **MainViewModel**에서만 사용
- 다른 곳에서는 직접 NavController 사용

### 3. **Coroutine 복잡성**
- Flow를 collect하는 코루틴 로직이 불필요

## **개선 방안**

### 1. **MainActivity에서 직접 처리**
```kotlin
class MainActivity : ComponentActivity() {
 private val viewModel: MainViewModel by viewModels()
 private lateinit var navController: NavController

 override fun onCreate(savedInstanceState: Bundle?) {
 super.onCreate(savedInstanceState)

 // ... 기존 코드 ...

 setContent {
 navController = rememberNavController()

 // NavigationHelper flow collect 로직 제거
 LaunchedEffect(Unit) {
 lifecycleScope.launch {
 lifecycle.repeatOnLifecycle(Lifecycle.State.STARTED) {
 // NavigationHelper 관련 코드 제거
 launch {
 viewModel.eventHelper.eventChannel.collect { event ->
 when (event) {
 is TraceEvent.ShowSnackBar -> snackBarHostState.showSnackbar(event.message)
 }
 }
 }
 }
 }
 }

 // ... 나머지 UI 코드 ...
 }

 // 직접 네비게이션 처리
 if (intent.extras != null && intent.getStringExtra("type") != null && intent.getStringExtra("id") != null) {
 handleNotificationIntent(intent)
 } else {
 viewModel.checkSession { route, popUpTo ->
 navigateDirectly(route, popUpTo)
 }
 requestNotificationPermission(this)
 }
 }

 private fun navigateDirectly(route: Route, popUpTo: Boolean = false) {
 val navOptions = navOptions {
 if (popUpTo) {
 popUpTo(0) { inclusive = true }
 }
 launchSingleTop = true
 }
 navController.navigate(route, navOptions)
 }

 private fun handleNotificationIntent(intent: Intent) {
 val notificationId = intent.getStringExtra("id") ?: return
 val type = intent.getStringExtra("type") ?: return

 viewModel.readNotification(notificationId)

 when (type) {
 "MISSION" -> {
 navigateDirectly(MissionGraph.MissionRoute, popUpTo = true)
 }
 "COMMENT", "EMOTION" -> {
 intent.getStringExtra("postId")?.toIntOrNull()?.let { postId ->
 navController.navigate(HomeGraph.HomeRoute, navOptions {
 popUpTo(0) { inclusive = true }
 launchSingleTop = true
 })
 navController.navigate(HomeGraph.PostRoute(postId), navOptions {
 launchSingleTop = true
 })
 }
 }
 }
 }
}
```

### 2. **MainViewModel 수정**
```kotlin
@HiltViewModel
class MainViewModel @Inject constructor(
 val eventHelper: EventHelper,
 private val userRepository: UserRepository,
 private val notificationRepository: NotificationRepository
) : ViewModel() {

 fun checkSession(onResult: (Route, Boolean) -> Unit) = viewModelScope.launch {
 userRepository.checkTokenHealth().onSuccess { isExpired ->
 if (!isExpired) {
 onResult(HomeGraph.HomeRoute, true)
 } else {
 onResult(AuthGraph.LoginRoute, true)
 }
 }.onFailure {
 onResult(AuthGraph.LoginRoute, true)
 }
 }

 fun readNotification(notificationId: String) = viewModelScope.launch {
 notificationRepository.readNotification(notificationId)
 }
}
```

