 userRepository.checkTokenHealth().fold(
 onSuccess = { isExpired ->
 _initialRoute.value = if (isExpired) AuthGraph.LoginRoute else HomeGraph.HomeRoute
 },
 onFailure = {
 _initialRoute.value = AuthGraph.LoginRoute
 }
 )
 }

 fun readNotification(notificationId: String) = viewModelScope.launch {
 notificationRepository.readNotification(notificationId)
 }
}
