## **현재 프로젝트의 네비게이션 처리 패턴 분석**

### **발견된 패턴들**

#### **1. Channel + Flow 패턴 (가장 일반적)**
```kotlin
// ViewModel
private val _eventChannel = Channel<LoginEvent>()
val eventChannel = _eventChannel.receiveAsFlow()

internal fun loginKakao(idToken: String) = viewModelScope.launch {
 // 비즈니스 로직
 _eventChannel.send(LoginEvent.NavigateToHome)
}

// Composable
LaunchedEffect(true) {
 viewModel.eventChannel.collect { event ->
 when (event) {
 is LoginEvent.NavigateToHome -> navigateToHome()
 is LoginEvent.NavigateEditProfile -> navigateToEditProfile(event.signUpToken, event.providerId)
 }
 }
}
```

#### **2. EventHelper 패턴 (공통 이벤트용)**
```kotlin
// ViewModel
viewModel.eventHelper.sendEvent(TraceEvent.ShowSnackBar("로그인에 실패했습니다"))

// MainActivity에서 전역 처리
viewModel.eventHelper.eventChannel.collect { event ->
 when (event) {
 is TraceEvent.ShowSnackBar -> snackBarHostState.showSnackbar(event.message)
 }
}
```

#### **3. NavigationHelper 패턴 (현재 제거 예정)**
```kotlin
// 기존 방식 (복잡함)
navigationHelper.navigate(NavigationEvent.To(HomeGraph.HomeRoute, popUpTo = true))
```

#### **4. 직접 콜백 패턴**
```kotlin
// Navigation 확장 함수 활용
navController.navigateToHome()
navController.navigateToPost(postFeed)
```

### **통일된 네비게이션 패턴 제안**

#### **권장 패턴: Sealed Class Event + Channel**

```kotlin
// 1. 각 ViewModel에서 Navigation Event 정의
sealed class HomeNavigationEvent {
 data class NavigateToPost(val postFeed: PostFeed) : HomeNavigationEvent()
 data object NavigateToSearch : HomeNavigationEvent()
 data object NavigateToWritePost : HomeNavigationEvent()
 data object NavigateBack : HomeNavigationEvent()
}

// 2. ViewModel에서 Event 발송
@HiltViewModel
class HomeViewModel @Inject constructor(...) : ViewModel() {
 private val _navigationEvent = Channel<HomeNavigationEvent>()
 val navigationEvent = _navigationEvent.receiveAsFlow()

 fun navigateToPost(postFeed: PostFeed) = viewModelScope.launch {
 _navigationEvent.send(HomeNavigationEvent.NavigateToPost(postFeed))
 }
}

// 3. Composable에서 Event 처리
@Composable
internal fun HomeRoute(
 navigateToPost: (PostFeed) -> Unit,
 navigateToSearch: () -> Unit,
 navigateToWritePost: () -> Unit,
 viewModel: HomeViewModel = hiltViewModel()
) {
 LaunchedEffect(Unit) {
 viewModel.navigationEvent.collect { event ->
 when (event) {
 is HomeNavigationEvent.NavigateToPost -> navigateToPost(event.postFeed)
 is HomeNavigationEvent.NavigateToSearch -> navigateToSearch()
 is HomeNavigationEvent.NavigateToWritePost -> navigateToWritePost()
 is HomeNavigationEvent.NavigateBack -> navigateBack()
 }
 }
 }

 HomeScreen(
 onPostClick = viewModel::navigateToPost,
 onSearchClick = viewModel::navigateToSearch,
 onWriteClick = viewModel::navigateToWritePost
 )
}
```

### **통일 작업이 필요한 부분들**

#### **1. 일관성 없는 이벤트 처리**
- **LoginViewModel**: `LoginEvent` 사용 ✅
- **HomeViewModel**: `HomeEvent` (네비게이션 + 기타 혼재) ⚠️
- **PostViewModel**: `PostEvent` (네비게이션 없음, EventHelper만 사용) ⚠️

#### **2. 네이밍 컨벤션 통일**
```kotlin
// 현재 (혼재)
sealed class LoginEvent
sealed class HomeEvent 
sealed class PostEvent

// 제안 (통일)
sealed class LoginNavigationEvent
sealed class HomeNavigationEvent
sealed class PostNavigationEvent
```

#### **3. EventHelper vs Navigation Event 분리**
```kotlin
// EventHelper: UI 상태 변경 (SnackBar, Dialog 등)
eventHelper.sendEvent(TraceEvent.ShowSnackBar("에러 메시지"))

// NavigationEvent: 화면 전환
_navigationEvent.send(NavigationEvent.NavigateToHome)
```

### **통일된 베이스 클래스 제안**

```kotlin
// BaseViewModel.kt
abstract class BaseViewModel : ViewModel() {
 private val _navigationEvent = Channel<NavigationEvent>()
 val navigationEvent = _navigationEvent.receiveAsFlow()

 protected fun navigate(event: NavigationEvent) = viewModelScope.launch {
 _navigationEvent.send(event)
 }

 abstract sealed class NavigationEvent
}

// 사용 예시
class HomeViewModel : BaseViewModel() {
 sealed class Event : NavigationEvent() {
 data class NavigateToPost(val postFeed: PostFeed) : Event()
 data object NavigateToSearch : Event()
 }

 fun onPostClick(postFeed: PostFeed) {
 navigate(Event.NavigateToPost(postFeed))
 }
}
```

이렇게 통일하면 **일관성 있고 예측 가능한 네비게이션 패턴**을 구축할 수 있습니다! "}]}]}}
